const base='http://127.0.0.1:17448';
const expected={
 agentId:'agent-media',
 oldUrl:'https://chatgpt.com/g/g-p-6ab839fa4f8c81919adad01c4a5497dc-sv/c/6ab8b24f-9c40-83eb-9b7b-766af74defe0',
 newUrl:'https://chatgpt.com/g/g-p-6ab839fa4f8c81919adad01c4a5497dc-sv/c/6abda64b-aac4-83eb-adee-dc7143ca5d2b',
 projectId:'project-g-p-6ab839fa4f8c81919adad01c4a5497dc',
 profileId:'ef72920c-cfe7-4824-a79b-7a0e0943ce7e',
 branch:'agent/media-r26-local-windows-render-gate-20261006',
 head:'b11a93664f9b64bf6da626119758c841a0a75c1e'
};
const [mc,pr]=await Promise.all([
 fetch(base+'/api/supervisor-watchdog/managed-chats?inspect=0').then(r=>r.json()),
 fetch(base+'/api/supervisor-watchdog/projects?inspect=0').then(r=>r.json())
]);
const chats=mc.chats||[]; const projects=pr.projects||[];
const a=chats.find(x=>x.id===expected.agentId);
const p=projects.find(x=>x.id===expected.projectId);
if(!a||!p) throw new Error('expected media/project record missing');
if(a.url!==expected.oldUrl) throw new Error('media old URL precondition changed: '+a.url);
if(String(a.profileId||'')!==expected.profileId) throw new Error('media profile precondition changed');
if(String(p.profileId||'')!==expected.profileId) throw new Error('project profile mismatch');
if(chats.some(x=>x.id!==a.id&&x.url===expected.newUrl)) throw new Error('new Media URL already owned by another managed record');
const prev=[...(a.chatHistory||[])]; if(a.url&&!prev.includes(a.url))prev.push(a.url);
a.predecessorUrl=a.url;
a.chatHistory=prev.slice(-50);
a.url=expected.newUrl;
a.projectId=expected.projectId;
a.repository='foto6/video2';
a.branch=expected.branch;
a.gitHead=expected.head;
a.role='media';
a.enabled=true;
a.rotateWithProject=true;
p.rotationPolicy={...(p.rotationPolicy||{}),enabled:true,onContextLimit:true,onMissingChat:true,keepPredecessor:true,requireHighMode:true};
const putM=await fetch(base+'/api/supervisor-watchdog/managed-chats',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({managedChats:chats})});
const jm=await putM.json(); if(!putM.ok) throw new Error('managed PUT failed '+putM.status+' '+JSON.stringify(jm));
const putP=await fetch(base+'/api/supervisor-watchdog/projects',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({managedProjects:projects})});
const jp=await putP.json(); if(!putP.ok) throw new Error('project PUT failed '+putP.status+' '+JSON.stringify(jp));
process.stdout.write(JSON.stringify({
 state:'APPLIED',
 media:{id:a.id,url:a.url,predecessorUrl:a.predecessorUrl,projectId:a.projectId,branch:a.branch,gitHead:a.gitHead,historyCount:a.chatHistory.length},
 project:{id:p.id,rotationPolicy:p.rotationPolicy}
}));

